package dev.xardas.nekoroftbchunkscobblemonicons.client;

import dev.ftb.mods.ftblibrary.config.NameMap;
import net.minecraft.network.chat.Component;

/**
 * Picture of the caught badge. Every picture has a texture per badge color and a gray "faded" one
 * in textures/badge/&lt;id&gt;/ (generated by tools/badges.py).
 */
public enum BadgeIcon {
    BALL("ball"),
    CAT("cat"),
    STAR("star"),
    CROSS("cross"),
    EYE("eye"),
    EXCLAMATION("exclamation"),
    QUESTION("question");

    public static final NameMap<BadgeIcon> NAME_MAP = NameMap.of(BALL, values())
            .id(icon -> icon.id)
            .name(icon -> Component.translatable("nekoroftbchunkscobblemonicons.badge_icon." + icon.id))
            .create();

    public final String id;

    BadgeIcon(String id) {
        this.id = id;
    }

    /** @param color null for the faded (gray) badge */
    public String texture(OutlineColor color) {
        return "textures/badge/" + id + "/" + (color == null ? "faded" : color.id) + ".png";
    }
}
